	--vscode-editor-placeholder-foreground: var(--vscode-editorGhostText-foreground);
}

.monaco-editor .editorPlaceholder {
		top: 0px;
		position: absolute;
		overflow: hidden;
		text-overflow: ellipsis;
		text-wrap: nowrap;
		pointer-events: none;

		color: var(--vscode-editor-placeholder-foreground);
	}
